#!/bin/sh
printf 'DOCKER_CONFIG=%s HOME=%s DOCKER_HOST=%s args=%s\n' "${DOCKER_CONFIG-unset}" "${HOME-unset}" "${DOCKER_HOST-unset}" "$*" >>"${DOCKER_CONFIG:-/nonexistent}/seen" 2>/dev/null
[ "$1 $2" = 'context inspect' ] || exit 1
case $5 in
colima) echo unix:///stub/colima.sock ;;
bad) echo 'no endpoint here' ;;
*) exit 1 ;;
esac
